class Handler(BaseHTTPRequestHandler):
    def base_url(self):
        return f"http://{self.headers.get('Host', 'localhost')}"

    def _body(self):
        length = int(self.headers.get("Content-Length", 0) or 0)
        if not length:
            return {}
        try:
            return json.loads(self.rfile.read(length))
        except Exception:
            return {}

    def do_GET(self):
        self._guarded(self._do_GET)

    def do_POST(self):
        self._guarded(self._do_POST)

    def do_PUT(self):
        self._guarded(self._do_PUT)

    def do_DELETE(self):
        self._guarded(self._do_DELETE)

    def _guarded(self, handler):
        # No route handler here may crash the request thread on a real
        # failure (a broken database file, a bad value from the client) --
        # found by exactly that happening once: an uncaught exception left
        # the client with a reset connection instead of a real 500, and the
        # traceback printed to stderr instead of anywhere a caller could see
        # it. respond() may itself have already sent a partial response by
        # the time something fails downstream of it, so this is a backstop,
        # not the primary error path for handlers that build their own
        # responses.
        try:
            handler()
        except Exception as exc:
            try:
                respond(self, 500, {"error": str(exc)})
            except Exception:
                pass  # headers already sent; nothing more this response can do

    def _do_GET(self):
        parsed = urlparse(self.path)
        path, qs = parsed.path, parse_qs(parsed.query)
        if path == "/" or path == "":
            path = "/index.html"
        if path == "/favicon.ico":
            # Browsers request this unconditionally; a plain 404 shows up as a
            # console error on every single page load with nothing to fix.
            self.send_response(204)
            self.end_headers()
            return
        if path.startswith("/static/") or re.match(r"^/[\w.-]+\.html$", path):
            self._serve_static(path.lstrip("/"))
            return
        if path.startswith("/documents/"):
            self._serve_document(path[len("/documents/"):])
            return
        if path == '/api/projects':
            self.list_projects(); return
        if path.startswith('/api/projects/'):
            self.get_projects(path[len('/api/projects/'):]); return
        if path.startswith('/api/history/projects/'):
            self.history_projects(path[len('/api/history/projects/'):]); return
        if path == '/api/tasks':
            self.list_tasks(); return
        if path.startswith('/api/tasks/'):
            self.get_tasks(path[len('/api/tasks/'):]); return
        if path.startswith('/api/history/tasks/'):
            self.history_tasks(path[len('/api/history/tasks/'):]); return
        if path == '/api/comments':
            self.list_comments(); return
        if path.startswith('/api/comments/'):
            self.get_comments(path[len('/api/comments/'):]); return
        if path.startswith('/api/history/comments/'):
            self.history_comments(path[len('/api/history/comments/'):]); return
        if path == '/api/reports/open_tasks_by_person':
            self.report_open_tasks_by_person(); return
        if path == '/api/reports/overdue_tasks':
            self.report_overdue_tasks(); return
        if path == '/api/notifications':
            self.list_notifications(); return

        respond(self, 404, {"error": "no route"})

    def _do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == '/api/projects':
            self.create_projects(self._body()); return
        if path == '/api/tasks':
            self.create_tasks(self._body()); return
        if path == '/api/comments':
            self.create_comments(self._body()); return
        if path.startswith('/api/moves/tasks/'):
            self.move_tasks(path[len('/api/moves/tasks/'):], self._body()); return
        if path.startswith('/api/actions/tasks/'):
            self.action_tasks(path[len('/api/actions/tasks/'):], self._body()); return
        if path == '/api/jobs/run':
            self.run_jobs(); return

        respond(self, 404, {"error": "no route"})

    def _do_PUT(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path.startswith('/api/projects/'):
            self.update_projects(path[len('/api/projects/'):], self._body()); return
        if path.startswith('/api/tasks/'):
            self.update_tasks(path[len('/api/tasks/'):], self._body()); return
        if path.startswith('/api/comments/'):
            self.update_comments(path[len('/api/comments/'):], self._body()); return

        respond(self, 404, {"error": "no route"})

    def _do_DELETE(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path.startswith('/api/projects/'):
            self.delete_projects(path[len('/api/projects/'):]); return
        if path.startswith('/api/tasks/'):
            self.delete_tasks(path[len('/api/tasks/'):]); return
        if path.startswith('/api/comments/'):
            self.delete_comments(path[len('/api/comments/'):]); return

        respond(self, 404, {"error": "no route"})

    def _serve_static(self, rel):
        rel = rel[len("static/"):] if rel.startswith("static/") else rel
        fp = os.path.join(STATIC_DIR, rel)
        if not os.path.abspath(fp).startswith(os.path.abspath(STATIC_DIR)) or not os.path.isfile(fp):
            respond(self, 404, {"error": "not found"}); return
        with open(fp, "rb") as f:
            body = f.read()
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _serve_document(self, rel):
        doc_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "documents")
        fp = os.path.join(doc_dir, rel)
        if not os.path.abspath(fp).startswith(os.path.abspath(doc_dir)) or not os.path.isfile(fp):
            respond(self, 404, {"error": "not found"}); return
        with open(fp, "rb") as f:
            body = f.read()
        self.send_response(200)
        self.send_header("Content-Type", "application/pdf" if fp.endswith(".pdf") else "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

