    def update_projects(self, record_id, body):
        _nconn = get_db()
        try:
            _before = _nconn.execute("SELECT * FROM projects WHERE id = ?", (record_id,)).fetchone()
            if _before is None:
                return respond(self, 404, {"error": "not found"})
            values = [body.get('Name'), body.get('Description'), body.get('Owner'), body.get('Due date'), body.get('Colour'), now_iso(), record_id]
            _nconn.execute("UPDATE projects SET [name] = ?, [description] = ?, [owner] = ?, [due_date] = ?, [colour] = ?, updated_at = ? WHERE id = ?", values)
            _nconn.commit()
            _after = dict(_nconn.execute("SELECT * FROM projects WHERE id = ?", (record_id,)).fetchone())
            notified = []
            for _col in ['name', 'description', 'owner', 'due_date', 'colour']:
                if _after.get(_col) and _after.get(_col) != _before[_col]:
                    notified += notify(_nconn, NOTIFICATION_DECLS, "field_set",
                                       table='projects', row=_after, column=_col)
            if False and _after.get("stock_on_hand") is not None and _after.get("reorder_point") is not None:
                try:
                    if float(_after["stock_on_hand"]) <= float(_after["reorder_point"]):
                        notified += notify(_nconn, NOTIFICATION_DECLS, "threshold", table='projects', row=_after)
                except (TypeError, ValueError):
                    pass
            respond(self, 200, {"id": record_id, "notified": notified})
        finally:
            _nconn.close()

