    def move_tasks(self, row_id, body):
        """A declared person-moved edge, moved by one of its own roles."""
        transitions = [{"from": "To do", "to": "In progress", "mover": "roles", "roles": ["Member"]}, {"from": "In progress", "to": "Done", "mover": "roles", "roles": ["Member"]}, {"from": "Done", "to": "In progress", "mover": "roles", "roles": ["Member"]}, {"from": "In progress", "to": "To do", "mover": "roles", "roles": ["Member"]}]
        approvals = []
        conn = get_db()
        try:
            row = conn.execute("SELECT stage FROM tasks WHERE id = ?", (row_id,)).fetchone()
            if row is None:
                return respond(self, 404, {"error": "no such row"})
            try:
                stage_approval_gate.check_may_leave(conn, approvals, "tasks", row_id, row["stage"])
            except stage_approval_gate.NotApproved as err:
                return respond(self, 409, {"error": str(err), "waiting_for_approval": True})
            try:
                workflow_executor.transition(conn, "tasks", row_id, "stage", transitions,
                                             body.get("to"), body.get("role"))
            except workflow_executor.IllegalTransition as err:
                return respond(self, 409, {"error": str(err)})
            stage_history.record_transition(conn, "tasks", row_id, body.get("to"))
            done = run_transition_effects(conn, [], "tasks", row_id, body.get("to"))
            _row = dict(conn.execute("SELECT * FROM tasks WHERE id = ?", (row_id,)).fetchone())
            notified = notify(conn, NOTIFICATION_DECLS, "stage_reached", table="tasks", row=_row, stage=body.get("to"))
            respond(self, 200, {"from": row["stage"], "to": body.get("to"), "effects": done, "notified": notified})
        finally:
            conn.close()

    def action_tasks(self, tail, body):
        """A record's own declared extra button, run by the real
        custom_action_execution engine."""
        declared = {"Duplicate": {"name": "Duplicate", "who": ["Member"], "effect": {"op": "clone", "overrides": {"stage": "To do"}, "title_column": "title", "title_suffix": " (copy)"}}}
        row_id, _, action_name = tail.partition("/")
        action_name = urllib.parse.unquote(action_name)
        action = declared.get(action_name)
        if action is None:
            return respond(self, 404, {"error": "no declared action " + repr(action_name)})
        conn = get_db()
        try:
            try:
                result = run_custom_action(conn, action, 'tasks', row_id, body.get("role"), body.get("inputs") or {})
            except custom_action_execution.NotAllowed as err:
                return respond(self, 403, {"error": str(err)})
            except custom_action_execution.UnknownOperation as err:
                return respond(self, 400, {"error": str(err)})
            except ValueError as err:
                return respond(self, 400 if "needs a value" in str(err) else 404, {"error": str(err)})
            _row = conn.execute("SELECT * FROM " + 'tasks' + " WHERE id = ?", (row_id,)).fetchone()
            if _row is not None:
                result["notified"] = notify(conn, NOTIFICATION_DECLS, "custom_action",
                                            table='tasks', row=dict(_row), action=action_name)
            respond(self, 200, result)
        finally:
            conn.close()

